# import http.client
import json
import re
import sys
import os

# Convert decimal to binary value (used for code creation)
def dec2bin(val, nbbits):
    bits = []
    for i in range(nbbits):
        bits.append(str(val % 2))
        val = int((val - val % 2) / 2)
    bits.reverse()
    s = ""
    return s.join(bits)

# Convert binary to base64 (using 6 bits) (used for code creation)
def bin2base64(binary):
    charsetsBase64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_="
    base64txt = ""

    for i in range(0,len(binary),6):
        onechar64 = binary[i:i+6]
        onchar64add = ""
        if len(onechar64) < 6:
            for j in range(6-len(onechar64)):
                onchar64add += "0"

        onechar64 += onchar64add
        base64txt += charsetsBase64[int(onechar64, 2)]
    return base64txt

# Create a code based on codeDescription from attributes.json and inputs (gNBConfig)
def codeGenerator(codeDescription, inputs, verbose=False):
    i = 0
    index = 0
    bitsCodeValue = ""

    for i in inputs:
        if verbose:
            print("Add input for code: {} with value {}".format(i, inputs[i]))
        bitsCodeValue += dec2bin(inputs[i], codeDescription[i][1])
        index += 1

    return bin2base64(bitsCodeValue)

# Get tput values from one gNBConfig structure
def getTputValues(gNBConfig, harqProcess=False, latencyBudget=False, attributes=None, verbose=False):  # noqa: C901

    # Get all attributes in the structure codeDescription from attributes.json (used also in JavaScript for launching requests)
    codeDescription = {}
    if attributes is None :
        if len(sys.argv) > 1 :
            attributes = sys.argv[1]
        else :
            attributes = os.path.join(sys.path[0],'attributes.json')
    assert(os.path.isfile(attributes))
    with open(attributes, 'r') as f:
        configFile = json.load(f)
        for info in configFile["NRDim"]:
            codeDescription[info[0]] = info

    code = codeGenerator(codeDescription, gNBConfig, verbose=verbose)
    if verbose:
        print("Code found: {}".format(code))

    # Prepare the URL to execute Python:
    urlGet = "/NRDim_execServer.php?"
    urlGet += "co="+code

    if harqProcess :
        urlGet += "&hp=1"

    if latencyBudget :
        urlGet += "&lb=1"

    if verbose:
        print("URL used: {}".format(urlGet))

    # Launch URL request and get the result (in data)
    #connection = http.client.HTTPConnection("localhost",80)
    #connection = http.client.HTTPConnection("localhost",5555)
    #connection = http.client.HTTPConnection("5gtables.eecloud.dynamic.nsn-net.net",80) # ,context=ssl.create_default_context()
    #connection.request("GET", urlGet)
    #response = connection.getresponse()
    #data = str(response.read())
    data = ""
    # Launch REGEXP on request to get only the throughput:
    DLtput = re.search(r"DL tput: ([\d.]*)Mbps",data).groups()[0]
    ULtput = re.search(r"UL tput: ([\d.]*)Mbps",data).groups()[0]
    if harqProcess:
        harqDelayDL = re.search(r"harqDelayDL: ([\S.]*) slots",data).groups()[0]
        harqDelayUL = re.search(r"harqDelayUL: ([\S.]*) slots",data).groups()[0]

        maxHarqDL = re.search(r"maxHarqDL: ([\S.]*) procs",data).groups()[0]
        maxHarqUL = re.search(r"maxHarqUL: ([\S.]*) procs",data).groups()[0]

        k1resultmin = re.search(r"k1resultmin: ([\S.]*) slots",data).groups()[0]
        k1resultmax = re.search(r"k1resultmax: ([\S.]*) slots",data).groups()[0]
        averagek1 = re.search(r"averagek1: ([\S.]*) slots",data).groups()[0]

        k2resultmin = re.search(r"k2resultmin: ([\S.]*) slots",data).groups()[0]
        k2resultmax = re.search(r"k2resultmax: ([\S.]*) slots",data).groups()[0]
        averagek2 = re.search(r"averagek2: ([\S.]*) slots",data).groups()[0]

        DLmingapPDSCH = re.search(r"DLmingapPDSCH: ([\S.]*) slots",data).groups()[0]
        DLmaxgapPDSCH = re.search(r"DLmaxgapPDSCH: ([\S.]*) slots",data).groups()[0]
        DLavggapPDSCH = re.search(r"DLavggapPDSCH: ([\S.]*) slots",data).groups()[0]

        ULmingapPUSCH = re.search(r"ULmingapPUSCH: ([\S.]*) slots",data).groups()[0]
        ULmaxgapPUSCH = re.search(r"ULmaxgapPUSCH: ([\S.]*) slots",data).groups()[0]
        ULavggapPUSCH = re.search(r"ULavggapPUSCH: ([\S.]*) slots",data).groups()[0]

        ULmingapPUCCH = re.search(r"ULmingapPUCCH: ([\S.]*) slots",data).groups()[0]
        ULmaxgapPUCCH = re.search(r"ULmaxgapPUCCH: ([\S.]*) slots",data).groups()[0]
        ULavggapPUCCH = re.search(r"ULavggapPUCCH: ([\S.]*) slots",data).groups()[0]

        return [
            DLtput,
            ULtput,
            harqDelayDL,
            harqDelayUL,
            maxHarqDL,
            maxHarqUL,
            k1resultmin,
            k1resultmax,
            averagek1,
            k2resultmin,
            k2resultmax,
            averagek2,
            DLmingapPDSCH,
            DLmaxgapPDSCH,
            DLavggapPDSCH,
            ULmingapPUSCH,
            ULmaxgapPUSCH,
            ULavggapPUSCH,
            ULmingapPUCCH,
            ULmaxgapPUCCH,
            ULavggapPUCCH,
        ]

    return [DLtput, ULtput]

